package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

/** Real owned full old proof/current leaf locks, all verified before business mutation. */
class CatalogVersionBatchPermitTest extends CatalogVersionCommitPermitTest {
    List<CatalogVersionCommitPermitService.Captured> hundred(CatalogVersionCommitPermitService guard){var values=new ArrayList<CatalogVersionCommitPermitService.Captured>();for(int n=0;n<100;n++){String id=String.format(Locale.ROOT,"fictional-batch-%03d",n);f.jdbc.update("INSERT INTO source_run_items SELECT ?,run_id,source_id,revision,category,created_at,terminal_state,state,projection_decision,effective_valid,evidence_json,evidence_hash,entity_id,? FROM source_run_items WHERE id='fictional-current-item'",id,"fictional-batch-source-"+n);values.add(guard.capture("fictional-entity","fictional-analysis",id,f.clock.instant()).orElseThrow());}return List.copyOf(values);}
    @Test void FourCategorySingleBatchKeepsOriginalPermissionAndEmptyHasNoFakeProjection(){for(String cat:List.of("agent","skill","workflow","model")){initialize(cat,false);var guard=permits();var original=capture(guard);var full=write(()->guard.verifyAll(List.of(original)));assertSame(original.projection(),full.get(original.projection().memberId()));assertThrows(RuntimeException.class,full::clear);assertTrue(write(()->guard.verifyAll(List.of())).isEmpty());assertEquals(1,f.sends);}}
    @Test void ActualHundredCurrentLeavesVerifyInTheOriginalOneSecondWriterWithoutRepeatingOldProof(){var guard=permits();var all=hundred(guard);var full=write(()->guard.verifyAll(all));assertEquals(100,full.size());assertTrue(full.containsKey("fictional-batch-099"));for(var c:all)assertSame(c.projection(),full.get(c.projection().memberId()));assertEquals(1,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(1,f.sends);}
    @Test void ChangedLastNativeRawBodyWithoutRevisionRejectsAllBeforeAnyBusinessMutation(){var guard=permits();var all=hundred(guard);long revision=f.jdbc.queryForObject("SELECT revision FROM analyzed_entities",Long.class);f.jdbc.update("UPDATE source_run_items SET evidence_json=? WHERE id='fictional-batch-099'","{\"fictional_changed_raw\":true}");assertThrows(RuntimeException.class,()->write(()->{guard.verifyAll(all);f.jdbc.update("UPDATE analyzed_entities SET revision=revision+1");return true;}));assertEquals(revision,f.jdbc.queryForObject("SELECT revision FROM analyzed_entities",Long.class));assertEquals(1,f.sends);}
    @Test void DuplicateOverHundredForeignIssuerWrongTransactionAndRawAliasCannotGrantBatch(){var guard=permits();var original=capture(guard);assertThrows(RuntimeException.class,()->guard.verifyAll(List.of()));assertThrows(RuntimeException.class,()->write(()->guard.verifyAll(List.of(original,original))));assertThrows(GenerationFlowService.CapacityGuarded.class,()->write(()->guard.verifyAll(Collections.nCopies(101,original))));assertThrows(RuntimeException.class,()->write(()->permits().verifyAll(List.of(original))));var wrong=new TransactionTemplate(f.tx);wrong.setReadOnly(true);wrong.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);assertThrows(RuntimeException.class,()->wrong.execute(s->guard.verifyAll(List.of())));f.jdbc.update("UPDATE source_run_items SET source_id='fictional-foreign' WHERE id='fictional-current-item'");assertThrows(RuntimeException.class,()->write(()->guard.verifyAll(List.of(original))));assertEquals(1,f.sends);}
}
